function guard(box){
  const img = box.querySelector('img'); if(!img) return;
  img.addEventListener('error', ()=>{
    box.style.border=''; box.classList.remove('wm');
    box.removeAttribute('data-lb'); box.innerHTML = PH_HTML;
  }, {once:true});
}
