const STAMP = 'togogroup.uz';
const IC_ZOOM = `<svg viewBox="0 0 24 24"><circle cx="11" cy="11" r="7"/><path d="M20 20l-3.6-3.6M11 8.4v5.2M8.4 11h5.2"/></svg>`;
function shotBox(src, alt, key, idx){
  return `<div class="shot wm" data-lb="${key}" data-i="${idx}" style="border:1px solid var(--line)">`
       + `<img src="${src}" alt="${alt}" loading="lazy" draggable="false">`
       + `<span class="stamp">${STAMP}</span>`
       + `<span class="zoom">${IC_ZOOM}</span></div>`;
}
function fillPhotos(){
  Object.entries(PHOTOS).forEach(([k,arr])=>{
    const list=(arr||[]).filter(Boolean);
    const alt=(I18N[k+'t']||{})[L] || '';
    list.slice(0,4).forEach((src,i)=>{
      const box=document.querySelector(`[data-shot="${k}-${i}"]`);
      if(!box) return;
      box.style.border='1px solid var(--line)';
      box.classList.add('wm');
      box.setAttribute('data-lb', k); box.setAttribute('data-i', i);
      box.innerHTML=`<img src="${src}" alt="${alt}" loading="lazy" draggable="false">`
                  + `<span class="stamp">${STAMP}</span>`
                  + `<span class="zoom">${IC_ZOOM}</span>`;
      guard(box);
    });
    const gal=document.getElementById('gal-'+k);
    if(!gal) return;
    gal.innerHTML = list.length
      ? list.map((src,i)=>shotBox(src, alt, k, i)).join('')
      : Array.from({length:9},()=>`<div class="shot">${PH_HTML}</div>`).join('');
    if(list.length) gal.querySelectorAll('.shot').forEach(guard);
  });
}
fillPhotos();

