let view='home';
function go(v, push){
  const sec=document.querySelector(`section[data-view="${v}"]`);
  if(!sec) return;
  view=v;
  document.querySelectorAll('section[data-view]').forEach(x=>x.classList.toggle('show', x===sec));
  document.querySelectorAll('[data-go]').forEach(a=>{
    if(a.tagName==='A') a.classList.toggle('on', a.dataset.go===v);
  });
  document.querySelectorAll('[data-pfchip]').forEach(b=>
    b.classList.toggle('on', b.dataset.pfchip===v));
  document.body.classList.remove('nav-open');
  window.scrollTo(0,0);
  try{ if(push!==false && location.hash.slice(1)!==v && history.replaceState)
    history.replaceState(null,'','#'+v); }catch(_){}
  sec.querySelectorAll('.rv').forEach(el=>el.classList.add('in'));
}
document.addEventListener('click', e=>{
  const b=e.target.closest('[data-go]'); if(!b) return;
  e.preventDefault(); go(b.dataset.go);
});
addEventListener('hashchange',()=>go(location.hash.slice(1)||'home', false));

