function layoutSign(){
  const word = (I18N.signWord[L]||'REKLAMA').replace(/\s/g,'');
  const g = document.getElementById('signG');
  if(!g) return;
  const cells = [...g.querySelectorAll('.ln')];
  const N = Math.min(word.length, cells.length);
  const X0 = 138, W = 264, gap = 4;
  const cw = (W - (N-1)*gap) / N;
  const fs = Math.min(cw*0.62, 21);
  cells.forEach((c,i)=>{
    if(i >= N){ c.style.display='none'; return; }
    c.style.display='';
    c.style.animationDelay = (i*0.30)+'s';
    const x = X0 + i*(cw+gap);
    const r = c.querySelector('rect'), tx = c.querySelector('text');
    r.setAttribute('x', x.toFixed(1)); r.setAttribute('width', cw.toFixed(1));
    r.setAttribute('rx', Math.min(4, cw*0.16).toFixed(1));
    tx.setAttribute('x', (x+cw/2).toFixed(1));
    tx.setAttribute('font-size', fs.toFixed(1));
    tx.textContent = word[i];
  });
}

