/* ============================================================
   FON ANIMATSIYASI — LED matritsa + neon iz
   Sichqoncha ortidan yorug'lik yuguradi, nuqtalar LED ekran
   kabi yonadi, orqasida neon naycha izi qoladi.
   ============================================================ */
(function () {
  var host = document.getElementById('bgfx');
  if (!host) return;
  var reduce = !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);

  var cv = document.createElement('canvas');
  host.appendChild(cv);
  var ctx = cv.getContext('2d', { alpha: true });
  var off = document.createElement('canvas');
  var octx = off.getContext('2d');
  if (!ctx || !octx) { cv.remove(); return; }   /* canvas ishlamasa — fon oddiy qoladi */

  var SP = 27, DOT = 1.15;
  var W = 0, H = 0, DPR = 1, cols = 0, rows = 0;
  var tx = window.innerWidth * 0.5, ty = window.innerHeight * 0.38;
  var cx = tx, cy = ty, raf = 0, idle = 0;
  var trail = [];
  var RGB = [255, 198, 26];
  var baseCol = 'rgba(255,255,255,.055)';

  function parseColor(str) {
    str = (str || '').trim();
    if (str.charAt(0) === '#') {
      if (str.length === 4) {
        return [parseInt(str[1] + str[1], 16), parseInt(str[2] + str[2], 16), parseInt(str[3] + str[3], 16)];
      }
      return [parseInt(str.substr(1, 2), 16), parseInt(str.substr(3, 2), 16), parseInt(str.substr(5, 2), 16)];
    }
    var m = str.match(/(\d+)[,\s]+(\d+)[,\s]+(\d+)/);
    return m ? [+m[1], +m[2], +m[3]] : [255, 198, 26];
  }
  function rgba(a) { return 'rgba(' + RGB[0] + ',' + RGB[1] + ',' + RGB[2] + ',' + a + ')'; }

  function readTheme() {
    var cs = getComputedStyle(document.documentElement);
    RGB = parseColor(cs.getPropertyValue('--brand'));
    var light = document.documentElement.getAttribute('data-theme') === 'light';
    baseCol = light ? 'rgba(13,21,34,.075)' : 'rgba(255,255,255,.055)';
    drawBase();
  }

  function drawBase() {
    if (!W) return;
    octx.setTransform(DPR, 0, 0, DPR, 0, 0);
    octx.clearRect(0, 0, W, H);
    octx.fillStyle = baseCol;
    for (var i = 0; i <= cols; i++) {
      for (var j = 0; j <= rows; j++) {
        octx.beginPath();
        octx.arc(i * SP, j * SP, DOT, 0, 6.2832);
        octx.fill();
      }
    }
  }

  function resize() {
    DPR = Math.min(window.devicePixelRatio || 1, 2);
    W = window.innerWidth; H = window.innerHeight;
    cv.width = Math.round(W * DPR); cv.height = Math.round(H * DPR);
    cv.style.width = W + 'px'; cv.style.height = H + 'px';
    off.width = cv.width; off.height = cv.height;
    ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
    cols = Math.ceil(W / SP); rows = Math.ceil(H / SP);
    drawBase();
  }

  /* kursor atrofidagi nuqtalarni yoqish */
  function lit(px, py, R, power) {
    var i0 = Math.max(0, Math.floor((px - R) / SP)), i1 = Math.min(cols, Math.ceil((px + R) / SP));
    var j0 = Math.max(0, Math.floor((py - R) / SP)), j1 = Math.min(rows, Math.ceil((py + R) / SP));
    var R2 = R * R;
    for (var i = i0; i <= i1; i++) {
      var x = i * SP, dx = x - px;
      for (var j = j0; j <= j1; j++) {
        var y = j * SP, dy = y - py;
        var d2 = dx * dx + dy * dy;
        if (d2 > R2) continue;
        var f = 1 - Math.sqrt(d2) / R;
        f = f * f;
        var a = f * power;
        if (a < 0.012) continue;
        ctx.fillStyle = rgba(a.toFixed(3));
        ctx.beginPath();
        ctx.arc(x, y, DOT + f * 2.1, 0, 6.2832);
        ctx.fill();
      }
    }
  }

  function frame() {
    cx += (tx - cx) * 0.11;
    cy += (ty - cy) * 0.11;

    trail.push([cx, cy]);
    if (trail.length > 16) trail.shift();

    ctx.clearRect(0, 0, W, H);
    ctx.drawImage(off, 0, 0, W, H);

    /* yumshoq yorug'lik */
    var g = ctx.createRadialGradient(cx, cy, 0, cx, cy, 280);
    g.addColorStop(0, rgba(0.085));
    g.addColorStop(0.55, rgba(0.028));
    g.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.fillStyle = g;
    ctx.fillRect(cx - 280, cy - 280, 560, 560);

    /* neon naycha izi */
    if (trail.length > 3) {
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';
      ctx.shadowColor = rgba(0.55);
      ctx.shadowBlur = 14;
      ctx.strokeStyle = rgba(0.20);
      ctx.lineWidth = 2.4;
      ctx.beginPath();
      ctx.moveTo(trail[0][0], trail[0][1]);
      for (var k = 1; k < trail.length; k++) {
        var p = trail[k - 1], c = trail[k];
        ctx.quadraticCurveTo(p[0], p[1], (p[0] + c[0]) / 2, (p[1] + c[1]) / 2);
      }
      ctx.stroke();
      ctx.shadowBlur = 0;
    }

    /* yonayotgan nuqtalar */
    lit(cx, cy, 168, 0.62);
    for (var t = 0; t < trail.length; t += 3) {
      var w = (t / trail.length) * 0.22;
      if (w > 0.02) lit(trail[t][0], trail[t][1], 78, w);
    }

    /* kursor markazi */
    ctx.fillStyle = rgba(0.9);
    ctx.beginPath();
    ctx.arc(cx, cy, 2.6, 0, 6.2832);
    ctx.fill();

    raf = requestAnimationFrame(frame);
  }

  function move(x, y) { tx = x; ty = y; idle = 0; }

  window.addEventListener('resize', resize);
  window.addEventListener('pointermove', function (e) { move(e.clientX, e.clientY); }, { passive: true });
  window.addEventListener('touchmove', function (e) {
    var p = e.touches[0]; if (p) move(p.clientX, p.clientY);
  }, { passive: true });

  document.addEventListener('visibilitychange', function () {
    if (document.hidden) { cancelAnimationFrame(raf); raf = 0; }
    else if (!raf && !reduce) raf = requestAnimationFrame(frame);
  });

  window.__fxTheme = readTheme;

  resize();
  readTheme();
  if (reduce) {
    ctx.drawImage(off, 0, 0, W, H);
  } else {
    raf = requestAnimationFrame(frame);
  }
})();


