async function ask(text){
  if(busy||!text.trim()) return;
  busy=true; aiSend.disabled=true; greeted=true; aiChips.style.display='none';
  bubble('me',text); history.push({role:'user',content:text});
  aiInput.value=''; aiInput.style.height='auto';
  const dots=typing();
  try{
    const r=await fetch('https://api.anthropic.com/v1/messages',{
      method:'POST', headers:{'Content-Type':'application/json'},
      body:JSON.stringify({model:'claude-sonnet-4-6',max_tokens:1000,system:SYS(),messages:history.slice(-12)})});
    const data=await r.json(); dots.remove();
    const out=(data.content||[]).filter(x=>x.type==='text').map(x=>x.text).join('\\n').trim();
    if(!out) throw new Error('empty');
    bubble('bot',out); history.push({role:'assistant',content:out});
  }catch(e){ dots.remove(); bubble('err', t('aiErr')); history.pop(); }
  busy=false; aiSend.disabled=false; aiInput.focus();
}
