/* ============================================================
   RASM KO'RISH OYNASI (lightbox) + ARIZA OYNASI
   ============================================================ */
(function () {
  var TG = 'https://t.me/togo_group_pro';
  var lb = document.getElementById('lb');
  var lbImg = document.getElementById('lbImg');
  var lbTitle = document.getElementById('lbTitle');
  var lbCount = document.getElementById('lbCount');
  var lbDesc = document.getElementById('lbDesc');
  var lbChips = document.getElementById('lbChips');
  var od = document.getElementById('od');
  if (!lb || !od) return;

  var cur = { key: null, i: 0, list: [] };
  var ctx = '';

  function populateAllPortfolioImages() {
    if (typeof PHOTOS === 'undefined') return;
    
    // 1. Main portfolio section preview thumbnails
    document.querySelectorAll('.shot[data-shot]').forEach(function (el) {
      var attr = el.getAttribute('data-shot');
      if (!attr) return;
      var parts = attr.split('-');
      var key = parts[0];
      var idx = parseInt(parts[1], 10) || 0;
      var list = PHOTOS[key] || [];
      if (list[idx]) {
        var src = list[idx];
        el.setAttribute('data-lb', key);
        el.setAttribute('data-i', idx);
        el.style.cursor = 'pointer';
        el.style.display = '';
        el.innerHTML = '<img src="' + src + '" alt="TOGO Portfolio" loading="lazy" style="width:100%;height:100%;object-fit:cover;border-radius:12px;display:block;" onerror="this.parentNode.style.display=\'none\'" />';
      } else {
        el.style.display = 'none';
      }
    });

    // 2. Category detail gallery pages (#gal-f1, #gal-f2, ... #gal-f8)
    ['f1', 'f2', 'f3', 'f4', 'f5', 'f6', 'f7', 'f8'].forEach(function(key) {
      var container = document.getElementById('gal-' + key);
      if (!container) return;
      var list = PHOTOS[key] || [];
      var html = '';
      list.forEach(function(src, i) {
        html += '<div class="shot" data-lb="' + key + '" data-i="' + i + '" style="cursor:pointer;aspect-ratio:4/3;overflow:hidden;border-radius:12px;background:var(--soft);border:1px solid var(--line);">';
        html += '<img src="' + src + '" alt="TOGO Portfolio ' + (i + 1) + '" loading="lazy" style="width:100%;height:100%;object-fit:cover;display:block;" onerror="this.parentNode.style.display=\'none\'" />';
        html += '</div>';
      });
      container.innerHTML = html;
    });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', populateAllPortfolioImages);
  } else {
    populateAllPortfolioImages();
  }

  /* ---------- lightbox ---------- */
  function catName(key) {
    var row = I18N[key + 't'];
    return row ? row[L] : '';
  }
  function show(key, i) {
    var list = (PHOTOS[key] || []).filter(Boolean);
    if (!list.length) return;
    cur.key = key;
    cur.list = list;
    cur.i = (i + list.length) % list.length;
    lbImg.src = list[cur.i];
    lbImg.alt = catName(key);
    fillInfo(key);
    lbCount.textContent = (cur.i + 1) + ' ' + t('lbOf') + ' ' + list.length;
    lb.hidden = false;
    document.body.classList.add('modal');
  }
  function fillInfo(key) {
    lbTitle.textContent = catName(key);
    var dsc = I18N[key + 'd'];
    lbDesc.textContent = dsc ? dsc[L] : '';
    var out = '';
    ['a', 'b', 'c'].forEach(function (x) {
      var row = I18N[key + x];
      if (row) out += '<span class="chip">' + row[L] + '</span>';
    });
    lbChips.innerHTML = out;
  }
  function closeLb() { lb.hidden = true; lbImg.removeAttribute('src'); unlock(); }
  function step(d) { if (cur.key) show(cur.key, cur.i + d); }

  document.addEventListener('click', function (e) {
    var shot = e.target.closest('[data-lb]');
    if (shot && shot.querySelector('img')) {
      e.preventDefault();
      show(shot.getAttribute('data-lb'), +shot.getAttribute('data-i') || 0);
    }
  });
  document.getElementById('lbClose').addEventListener('click', closeLb);
  document.getElementById('lbPrev').addEventListener('click', function (e) { e.stopPropagation(); step(-1); });
  document.getElementById('lbNext').addEventListener('click', function (e) { e.stopPropagation(); step(1); });
  lb.addEventListener('click', function (e) { if (e.target === lb || e.target.classList.contains('lbwrap')) closeLb(); });
  document.getElementById('lbOrder').addEventListener('click', function () {
    var name = catName(cur.key);
    closeLb();
    openOrder(name);
  });

  /* ---------- ariza oynasi ---------- */
  function unlock() {
    if (lb.hidden && od.hidden) document.body.classList.remove('modal');
  }
  function openOrder(context) {
    ctx = context || '';
    var note = document.getElementById('odNote');
    if (ctx && !note.value) note.value = ctx;
    od.hidden = false;
    document.body.classList.add('modal');
    setTimeout(function () { document.getElementById('odName').focus(); }, 220);
  }
  function closeOrder() { od.hidden = true; unlock(); }
  window.__openOrder = openOrder;

  document.addEventListener('click', function (e) {
    var b = e.target.closest('[data-order]');
    if (b) { e.preventDefault(); openOrder(b.getAttribute('data-order') || ''); }
  });
  document.getElementById('odClose').addEventListener('click', closeOrder);
  od.addEventListener('click', function (e) { if (e.target === od) closeOrder(); });

  document.getElementById('odSend').addEventListener('click', function () {
    var nm = document.getElementById('odName').value.trim();
    var ph = document.getElementById('odPhone').value.trim();
    var nt = document.getElementById('odNote').value.trim();
    if (!nm || !ph) { alert(t('ordReq')); return; }
    var lines = [
      t('ordTitle') + ' — TOGO GROUP ADVERTISING',
      t('ordName') + ': ' + nm,
      t('ordPhone') + ': ' + ph
    ];
    if (nt) lines.push(t('ordNote') + ': ' + nt);
    window.open(TG + '?text=' + encodeURIComponent(lines.join('\n')), '_blank', 'noopener');
  });

  document.addEventListener('keydown', function (e) {
    if (e.key === 'Escape') { if (!lb.hidden) closeLb(); else if (!od.hidden) closeOrder(); }
    if (!lb.hidden) {
      if (e.key === 'ArrowLeft') step(-1);
      if (e.key === 'ArrowRight') step(1);
    }
  });

  /* barmoq bilan surish */
  var sx = 0;
  lb.addEventListener('touchstart', function (e) { sx = e.touches[0].clientX; }, { passive: true });
  lb.addEventListener('touchend', function (e) {
    var dx = e.changedTouches[0].clientX - sx;
    if (Math.abs(dx) > 55) step(dx < 0 ? 1 : -1);
  }, { passive: true });

  /* til almashganda matnlarni yangilash */
  window.__orderLang = function () {
    document.querySelectorAll('#lb [data-i18n],#od [data-i18n]').forEach(function (el) {
      var v = (I18N[el.dataset.i18n] || {})[L];
      if (v !== undefined) el.textContent = v;
    });
    document.querySelectorAll('#od [data-ph]').forEach(function (el) {
      var v = (I18N[el.dataset.ph] || {})[L];
      if (v) el.placeholder = v;
    });
    if (cur.key && !lb.hidden) {
      fillInfo(cur.key);
      lbCount.textContent = (cur.i + 1) + ' ' + t('lbOf') + ' ' + cur.list.length;
    }
  };
  window.__orderLang();
})();
